function(container, apiUrl, tables) {
  let currentProducts = [];
  let selectedProducts = new Set();
  let currentView = 'grid';

  // 商品データを取得（商品マスタ + 在庫マスタを結合）
  function getProductsWithStock() {
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const stocks = tables.find(t => t.tableName === '在庫マスタ')?.records || [];
    const categories = tables.find(t => t.tableName === '商品カテゴリマスタ')?.records || [];

    return products.map(product => {
      const stock = stocks.find(s => s.商品ID === product.商品ID) || {};
      const category = categories.find(c => c.カテゴリID === product.カテゴリID) || {};

      return {
        ...product,
        在庫数: stock.現在在庫数 || 0,
        在庫状態: stock.在庫状態 || '在庫切れ',
        カテゴリ名: category.カテゴリ名 || '未分類'
      };
    });
  }

  // グリッドビューの商品カード生成
  function renderGridView(products) {
    const gridView = container.querySelector('#grid-view');
    gridView.innerHTML = products.map(product => `
      <div class="bg-main rounded-lg p-4 border" style="border-color: var(--border);">
        <div class="flex justify-between items-start mb-2">
          <input 
            type="checkbox" 
            class="compare-checkbox" 
            data-product-id="${product.商品ID}"
            style="accent-color: var(--primary);"
            ${selectedProducts.has(product.商品ID) ? 'checked' : ''}
          />
          <span class="text-xs px-2 py-1 rounded ${getStockBadgeClass(product.在庫状態)}">${product.在庫状態}</span>
        </div>

        <div class="w-full h-32 bg-gray-200 rounded mb-3 flex items-center justify-center" style="background: rgba(0,0,0,0.1);">
          <span class="text-xs" style="color: var(--text-muted);">画像</span>
        </div>

        <h4 class="font-medium text-sm mb-1 line-clamp-2" style="color: var(--text);">${product.商品名 || ''}</h4>
        <p class="text-xs mb-2" style="color: var(--text-muted);">${product.商品コード || ''}</p>
        <p class="text-xs mb-2" style="color: var(--text-muted);">${product.カテゴリ名}</p>

        <div class="flex justify-between items-center mb-3">
          <span class="font-bold" style="color: var(--primary);">¥${(product.単価 || 0).toLocaleString()}</span>
          <span class="text-xs" style="color: var(--text-muted);">在庫: ${product.在庫数}${product.単位 || ''}</span>
        </div>

        <button 
          class="w-full action-btn text-sm py-2 view-detail-btn" 
          data-product-id="${product.商品ID}"
          style="background: var(--primary); color: #fff; border: none; border-radius: 4px;"
        >
          詳細を見る
        </button>
      </div>
    `).join('');
  }

  // リストビューのテーブル行生成
  function renderListView(products) {
    const tbody = container.querySelector('#product-tbody');
    tbody.innerHTML = products.map(product => `
      <tr data-product-id="${product.商品ID}">
        <td>
          <input 
            type="checkbox" 
            class="compare-checkbox" 
            data-product-id="${product.商品ID}"
            style="accent-color: var(--primary);"
            ${selectedProducts.has(product.商品ID) ? 'checked' : ''}
          />
        </td>
        <td>
          <div class="w-12 h-12 bg-gray-200 rounded flex items-center justify-center" style="background: rgba(0,0,0,0.1);">
            <span class="text-xs" style="color: var(--text-muted);">画像</span>
          </div>
        </td>
        <td style="color: var(--text);">${product.商品名 || ''}</td>
        <td style="color: var(--text-muted);">${product.商品コード || ''}</td>
        <td style="color: var(--text-muted);">${product.カテゴリ名}</td>
        <td style="color: var(--primary); font-weight: bold;">¥${(product.単価 || 0).toLocaleString()}</td>
        <td style="color: var(--text);">${product.在庫数}${product.単位 || ''}</td>
        <td>
          <span class="text-xs px-2 py-1 rounded ${getStockBadgeClass(product.在庫状態)}">${product.在庫状態}</span>
        </td>
        <td>
          <button 
            class="action-btn secondary text-sm px-3 py-1 view-detail-btn" 
            data-product-id="${product.商品ID}"
            style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); border-radius: 4px;"
          >
            詳細
          </button>
        </td>
      </tr>
    `).join('');
  }

  // 在庫状況のバッジクラス
  function getStockBadgeClass(status) {
    switch(status) {
      case '在庫あり': return 'bg-green-100 text-green-800';
      case '在庫僅少': return 'bg-yellow-100 text-yellow-800';
      case '在庫切れ': return 'bg-red-100 text-red-800';
      case '入荷待ち': return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  }

  // 商品一覧の再描画
  function renderProducts(products) {
    currentProducts = products;
    container.querySelector('#result-count').textContent = products.length;

    if (currentView === 'grid') {
      renderGridView(products);
    } else {
      renderListView(products);
    }

    updateCompareButton();
  }

  // 比較ボタンの状態更新
  function updateCompareButton() {
    const compareBtn = container.querySelector('#btn-compare');
    const count = selectedProducts.size;
    container.querySelector('#compare-count').textContent = count;
    compareBtn.disabled = count < 2;

    if (count >= 2) {
      compareBtn.style.background = 'var(--primary)';
      compareBtn.style.color = '#fff';
    } else {
      compareBtn.style.background = 'transparent';
      compareBtn.style.color = 'var(--text)';
    }
  }

  // 商品検索フィルタリング
  function filterProducts() {
    const keyword = container.querySelector('#search-keyword').value.toLowerCase();
    const category = container.querySelector('#category-filter').value;
    const priceMin = parseInt(container.querySelector('#price-min').value) || 0;
    const priceMax = parseInt(container.querySelector('#price-max').value) || Infinity;
    const stockFilter = container.querySelector('#stock-filter').value;

    const allProducts = getProductsWithStock();

    const filtered = allProducts.filter(product => {
      const matchKeyword = !keyword || 
        (product.商品名 || '').toLowerCase().includes(keyword) ||
        (product.商品コード || '').toLowerCase().includes(keyword);

      const matchCategory = !category || product.カテゴリ名 === category;
      const matchPrice = (product.単価 || 0) >= priceMin && (product.単価 || 0) <= priceMax;
      const matchStock = !stockFilter || product.在庫状態 === stockFilter;

      return matchKeyword && matchCategory && matchPrice && matchStock;
    });

    renderProducts(filtered);
  }

  // 比較モーダル表示
  function showCompareModal() {
    const selectedProductData = currentProducts.filter(p => selectedProducts.has(p.商品ID));
    const modal = container.querySelector('#compare-modal');
    const content = container.querySelector('#compare-content');

    if (selectedProductData.length < 2) return;

    // 比較テーブル生成
    content.innerHTML = `
      <table class="w-full">
        <thead>
          <tr>
            <th class="text-left p-2" style="color: var(--text);">項目</th>
            ${selectedProductData.map(p => `
              <th class="text-left p-2" style="color: var(--text);">${p.商品名}</th>
            `).join('')}
          </tr>
        </thead>
        <tbody>
          <tr>
            <td class="p-2 font-medium" style="color: var(--text);">商品コード</td>
            ${selectedProductData.map(p => `<td class="p-2" style="color: var(--text-muted);">${p.商品コード || ''}</td>`).join('')}
          </tr>
          <tr style="background: var(--bg-main);">
            <td class="p-2 font-medium" style="color: var(--text);">単価</td>
            ${selectedProductData.map(p => `<td class="p-2 font-bold" style="color: var(--primary);">¥${(p.単価 || 0).toLocaleString()}</td>`).join('')}
          </tr>
          <tr>
            <td class="p-2 font-medium" style="color: var(--text);">在庫数</td>
            ${selectedProductData.map(p => `<td class="p-2" style="color: var(--text);">${p.在庫数}${p.単位 || ''}</td>`).join('')}
          </tr>
          <tr style="background: var(--bg-main);">
            <td class="p-2 font-medium" style="color: var(--text);">在庫状況</td>
            ${selectedProductData.map(p => `
              <td class="p-2">
                <span class="text-xs px-2 py-1 rounded ${getStockBadgeClass(p.在庫状態)}">${p.在庫状態}</span>
              </td>
            `).join('')}
          </tr>
          <tr>
            <td class="p-2 font-medium" style="color: var(--text);">カテゴリ</td>
            ${selectedProductData.map(p => `<td class="p-2" style="color: var(--text-muted);">${p.カテゴリ名}</td>`).join('')}
          </tr>
          <tr style="background: var(--bg-main);">
            <td class="p-2 font-medium" style="color: var(--text);">最小発注数</td>
            ${selectedProductData.map(p => `<td class="p-2" style="color: var(--text);">${p.最小発注数 || 1}${p.単位 || ''}</td>`).join('')}
          </tr>
        </tbody>
      </table>
    `;

    modal.style.display = 'flex';
  }

  // 初期データ読み込み
  const allProducts = getProductsWithStock();
  renderProducts(allProducts);

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', filterProducts);

  // 検索フィールドでEnterキー
  container.querySelector('#search-keyword').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') filterProducts();
  });

  // ビュー切り替え
  container.querySelector('#btn-grid-view').addEventListener('click', () => {
    currentView = 'grid';
    container.querySelector('#grid-view').classList.remove('hidden');
    container.querySelector('#list-view').classList.add('hidden');
    container.querySelector('#btn-grid-view').style.background = 'var(--primary)';
    container.querySelector('#btn-grid-view').style.color = '#fff';
    container.querySelector('#btn-list-view').style.background = 'transparent';
    container.querySelector('#btn-list-view').style.color = 'var(--text)';
    renderProducts(currentProducts);
  });

  container.querySelector('#btn-list-view').addEventListener('click', () => {
    currentView = 'list';
    container.querySelector('#grid-view').classList.add('hidden');
    container.querySelector('#list-view').classList.remove('hidden');
    container.querySelector('#btn-list-view').style.background = 'var(--primary)';
    container.querySelector('#btn-list-view').style.color = '#fff';
    container.querySelector('#btn-grid-view').style.background = 'transparent';
    container.querySelector('#btn-grid-view').style.color = 'var(--text)';
    renderProducts(currentProducts);
  });

  // 比較チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('compare-checkbox')) {
      const productId = e.target.dataset.productId;
      if (e.target.checked) {
        selectedProducts.add(productId);
      } else {
        selectedProducts.delete(productId);
      }
      updateCompareButton();
    }
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.compare-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      const productId = cb.dataset.productId;
      if (e.target.checked) {
        selectedProducts.add(productId);
      } else {
        selectedProducts.delete(productId);
      }
    });
    updateCompareButton();
  });

  // 比較実行
  container.querySelector('#btn-compare').addEventListener('click', showCompareModal);

  // 比較モーダル閉じる
  container.querySelector('#close-compare').addEventListener('click', () => {
    container.querySelector('#compare-modal').style.display = 'none';
  });

  container.querySelector('#btn-close-compare').addEventListener('click', () => {
    container.querySelector('#compare-modal').style.display = 'none';
  });

  // 選択した商品で発注
  container.querySelector('#btn-select-for-order').addEventListener('click', () => {
    // 選択された商品IDをセッションストレージに保存して発注画面へ
    sessionStorage.setItem('selectedProducts', JSON.stringify(Array.from(selectedProducts)));
    window.showScreen('scr-1780291074387');
  });

  // 商品詳細ボタン（プレースホルダー）
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('view-detail-btn')) {
      const productId = e.target.dataset.productId;
      const product = currentProducts.find(p => p.商品ID === productId);
      if (product) {
        alert(`商品詳細\n\n商品名: ${product.商品名}\n商品コード: ${product.商品コード}\n単価: ¥${(product.単価 || 0).toLocaleString()}\n在庫: ${product.在庫数}${product.単位 || ''}\n状況: ${product.在庫状態}`);
      }
    }
  });
}

function(container, apiUrl, tables) {
  const productTbody = container.querySelector('#product-tbody');
  const categorySelect = container.querySelector('#category-select');
  const productSearch = container.querySelector('#product-search');
  const btnSearch = container.querySelector('#btn-search');
  const btnClear = container.querySelector('#btn-clear');
  const btnOrder = container.querySelector('#btn-order');
  const selectedCountEl = container.querySelector('#selected-count');
  const totalQuantityEl = container.querySelector('#total-quantity');
  const totalAmountEl = container.querySelector('#total-amount');

  let allProducts = [];
  let selectedItems = new Map(); // productId -> {product, quantity}

  // 商品テーブル再描画
  function renderProducts(products) {
    productTbody.innerHTML = products.map(product => {
      const specs = getProductSpecs(product.id);
      const stock = getProductStock(product.id);
      const price = getCustomerPrice(product.id);
      const selectedItem = selectedItems.get(product.id);
      const quantity = selectedItem ? selectedItem.quantity : 0;
      const subtotal = quantity * price;

      return `
        <tr data-id="${product.id}">
          <td style="text-align: center;">
            <input type="checkbox" class="product-checkbox" data-product-id="${product.id}" ${quantity > 0 ? 'checked' : ''} style="accent-color: var(--primary);">
          </td>
          <td style="font-family: monospace; font-size: 13px;">${product.商品コード || ''}</td>
          <td style="font-weight: 500;">${product.商品名 || ''}</td>
          <td style="font-size: 12px; color: var(--text-muted);">${specs}</td>
          <td style="text-align: right; font-weight: 500; color: ${stock > 10 ? 'var(--text)' : '#ff6a00'};">${stock}</td>
          <td style="text-align: right; font-weight: 500;">¥${price.toLocaleString()}</td>
          <td style="text-align: center;">
            <input type="number" class="quantity-input" data-product-id="${product.id}" 
                   value="${quantity}" min="0" max="${stock}" 
                   style="width: 80px; padding: 4px 8px; border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); text-align: right;">
          </td>
          <td style="text-align: right; font-weight: 600; color: var(--primary);">¥${subtotal.toLocaleString()}</td>
        </tr>
      `;
    }).join('');
  }

  // 商品仕様取得
  function getProductSpecs(productId) {
    const specsTable = tables.find(t => t.tableName === '商品仕様マスタ');
    if (!specsTable) return '';

    const specs = specsTable.records.filter(s => s.商品ID === productId && s.Web表示フラグ);
    return specs.map(s => `${s.仕様名}: ${s.仕様値}`).join(', ');
  }

  // 在庫数取得
  function getProductStock(productId) {
    const stockTable = tables.find(t => t.tableName === '在庫マスタ');
    if (!stockTable) return 0;

    const stock = stockTable.records.find(s => s.商品ID === productId);
    return stock ? stock.発注可能数量 : 0;
  }

  // 顧客別単価取得
  function getCustomerPrice(productId) {
    const customerPriceTable = tables.find(t => t.tableName === '顧客別単価マスタ');
    const productTable = tables.find(t => t.tableName === '商品マスタ');

    if (customerPriceTable) {
      const customerPrice = customerPriceTable.records.find(cp => 
        cp.商品ID === productId && cp.有効フラグ && 
        (!cp.適用終了日 || new Date(cp.適用終了日) > new Date())
      );
      if (customerPrice) return customerPrice.単価;
    }

    const product = productTable.records.find(p => p.id === productId);
    return product ? product.単価 : 0;
  }

  // 合計計算・表示更新
  function updateTotals() {
    const selectedCount = selectedItems.size;
    const totalQuantity = Array.from(selectedItems.values()).reduce((sum, item) => sum + item.quantity, 0);
    const totalAmount = Array.from(selectedItems.values()).reduce((sum, item) => {
      const price = getCustomerPrice(item.product.id);
      return sum + (item.quantity * price);
    }, 0);

    selectedCountEl.textContent = `${selectedCount}点`;
    totalQuantityEl.textContent = totalQuantity.toString();
    totalAmountEl.textContent = `¥${totalAmount.toLocaleString()}`;
  }

  // 商品検索
  function searchProducts() {
    const category = categorySelect.value;
    const keyword = productSearch.value.toLowerCase();

    let filtered = allProducts;

    if (category) {
      const categoryTable = tables.find(t => t.tableName === '商品カテゴリマスタ');
      if (categoryTable) {
        const categoryRecord = categoryTable.records.find(c => c.カテゴリコード === category);
        if (categoryRecord) {
          filtered = filtered.filter(p => p.カテゴリID === categoryRecord.id);
        }
      }
    }

    if (keyword) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(keyword) ||
        (p.商品コード || '').toLowerCase().includes(keyword)
      );
    }

    renderProducts(filtered);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const products = await window.aivicApi.list(1); // 商品マスタ
      if (products) {
        allProducts = products.filter(p => p.公開フラグ && p.販売状態 === '販売中');
        renderProducts(allProducts);
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
      allProducts = tables[1]?.records?.filter(p => p.公開フラグ && p.販売状態 === '販売中') || [];
      renderProducts(allProducts);
    }
  }

  // イベントリスナー
  btnSearch.addEventListener('click', searchProducts);

  // 商品選択・数量変更
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-checkbox')) {
      const productId = e.target.dataset.productId;
      const product = allProducts.find(p => p.id === productId);

      if (e.target.checked) {
        selectedItems.set(productId, { product, quantity: 1 });
        const quantityInput = container.querySelector(`input.quantity-input[data-product-id="${productId}"]`);
        if (quantityInput) quantityInput.value = '1';
      } else {
        selectedItems.delete(productId);
        const quantityInput = container.querySelector(`input.quantity-input[data-product-id="${productId}"]`);
        if (quantityInput) quantityInput.value = '0';
      }
      updateTotals();
    }

    if (e.target.classList.contains('quantity-input')) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;
      const product = allProducts.find(p => p.id === productId);
      const checkbox = container.querySelector(`input.product-checkbox[data-product-id="${productId}"]`);

      if (quantity > 0) {
        selectedItems.set(productId, { product, quantity });
        if (checkbox) checkbox.checked = true;
      } else {
        selectedItems.delete(productId);
        if (checkbox) checkbox.checked = false;
      }
      updateTotals();
    }
  });

  // クリアボタン
  btnClear.addEventListener('click', () => {
    if (!confirm('選択内容をクリアしますか？')) return;

    selectedItems.clear();
    container.querySelectorAll('.product-checkbox').forEach(cb => cb.checked = false);
    container.querySelectorAll('.quantity-input').forEach(input => input.value = '0');
    container.querySelector('#delivery-date').value = '';
    container.querySelector('#order-notes').value = '';
    updateTotals();
  });

  // 発注確定ボタン
  btnOrder.addEventListener('click', async () => {
    if (selectedItems.size === 0) {
      alert('商品を選択してください。');
      return;
    }

    const deliveryDate = container.querySelector('#delivery-date').value;
    const notes = container.querySelector('#order-notes').value;

    if (!confirm(`${selectedItems.size}点の商品を発注しますか？`)) return;

    try {
      // 発注履歴作成
      const orderData = {
        発注番号: `ORD-${Date.now()}`,
        顧客ID: 'customer-001', // 実際はログインユーザーから取得
        発注ステータス: '受注',
        発注日時: new Date().toISOString(),
        希望納期: deliveryDate || null,
        備考: notes,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者: 'system',
        更新者: 'system'
      };

      const savedOrder = await window.aivicApi.save(5, orderData); // 発注履歴

      if (savedOrder) {
        // 発注明細作成
        let detailNumber = 1;
        for (const [productId, item] of selectedItems) {
          const price = getCustomerPrice(productId);
          const detailData = {
            発注履歴ID: savedOrder.id,
            商品ID: productId,
            発注数量: item.quantity,
            単価: price,
            小計金額: item.quantity * price,
            明細番号: detailNumber++,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          };

          await window.aivicApi.save(6, detailData); // 発注明細
        }

        alert('発注が完了しました。');

        // 発注履歴画面へ遷移
        window.showScreen('scr-1780291083221');
      }
    } catch (error) {
      console.error('発注処理でエラーが発生しました:', error);
      alert('発注処理でエラーが発生しました。');
    }
  });

  // カテゴリ選択肢を動的に設定
  async function loadCategories() {
    try {
      const categories = await window.aivicApi.list(2); // 商品カテゴリマスタ
      if (categories) {
        const categoryOptions = categories
          .filter(c => c.有効フラグ)
          .sort((a, b) => a.表示順序 - b.表示順序)
          .map(c => `<option value="${c.カテゴリコード}">${c.カテゴリ名}</option>`)
          .join('');

        categorySelect.innerHTML = '<option value="">すべて</option>' + categoryOptions;
      }
    } catch (error) {
      console.error('カテゴリデータの読み込みに失敗しました:', error);
    }
  }

  // 初期化
  loadInitialData();
  loadCategories();
  updateTotals();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let filteredData = [];
  let currentPage = 1;
  let pageSize = 50;

  const tbody = container.querySelector("#order-history-tbody");
  const recordCount = container.querySelector("#record-count");
  const paginationInfo = container.querySelector("#pagination-info");
  const btnPrev = container.querySelector("#btn-prev");
  const btnNext = container.querySelector("#btn-next");

  // ステータスバッジのスタイル
  function getStatusBadge(status) {
    const styles = {
      '未確定': 'background: #fbbf24; color: #1a2a40; padding: 2px 6px; border-radius: 3px; font-size: 11px;',
      '確定': 'background: #3b82f6; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;',
      '出荷済': 'background: #10b981; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;',
      '完了': 'background: #6b7280; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;',
      'キャンセル': 'background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;'
    };
    return `<span style="${styles[status] || styles['未確定']}">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const start = (currentPage - 1) * pageSize;
    const end = start + pageSize;
    const pageRows = rows.slice(start, end);

    tbody.innerHTML = pageRows.map(r => `
      <tr data-id="${r.id}" class="border-b" style="border-color: var(--border);">
        <td class="py-2 px-3 text-sm" style="color: var(--text);">${r.発注番号 || ""}</td>
        <td class="py-2 px-3 text-sm" style="color: var(--text);">${r.発注日時 ? new Date(r.発注日時).toLocaleDateString('ja-JP') : ""}</td>
        <td class="py-2 px-3 text-sm" style="color: var(--text);">${r.商品名 || ""}</td>
        <td class="py-2 px-3 text-sm text-right" style="color: var(--text);">${r.発注数量 ? r.発注数量.toLocaleString() : ""}</td>
        <td class="py-2 px-3 text-sm text-right" style="color: var(--text);">${r.単価 ? "¥" + r.単価.toLocaleString() : ""}</td>
        <td class="py-2 px-3 text-sm text-right" style="color: var(--text);">${r.小計金額 ? "¥" + r.小計金額.toLocaleString() : ""}</td>
        <td class="py-2 px-3 text-sm text-center">${getStatusBadge(r.発注ステータス || "未確定")}</td>
        <td class="py-2 px-3 text-sm text-center">
          <button class="action-btn secondary text-xs px-2 py-1 mr-1 detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn text-xs px-2 py-1 reorder-btn" data-id="${r.id}">再発注</button>
        </td>
      </tr>
    `).join("");

    // 件数とページネーション情報を更新
    recordCount.textContent = `${rows.length}件の発注履歴`;
    const totalPages = Math.ceil(rows.length / pageSize);
    const displayStart = rows.length > 0 ? start + 1 : 0;
    const displayEnd = Math.min(end, rows.length);
    paginationInfo.textContent = `${displayStart}-${displayEnd} / ${rows.length}件`;

    // ページネーションボタンの状態更新
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  // フィルタリング関数
  function applyFilters() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const orderNumber = container.querySelector("#order-number").value.toLowerCase();
    const productName = container.querySelector("#product-name").value.toLowerCase();
    const category = container.querySelector("#category-filter").value;
    const status = container.querySelector("#status-filter").value;

    filteredData = currentData.filter(row => {
      // 発注日フィルタ
      if (startDate && row.発注日時) {
        const orderDate = new Date(row.発注日時).toISOString().split('T')[0];
        if (orderDate < startDate) return false;
      }
      if (endDate && row.発注日時) {
        const orderDate = new Date(row.発注日時).toISOString().split('T')[0];
        if (orderDate > endDate) return false;
      }

      // 発注番号フィルタ
      if (orderNumber && !(row.発注番号 || "").toLowerCase().includes(orderNumber)) return false;

      // 商品名フィルタ
      if (productName && !(row.商品名 || "").toLowerCase().includes(productName)) return false;

      // カテゴリフィルタ（商品マスタから取得する想定）
      if (category && row.カテゴリ !== category) return false;

      // ステータスフィルタ
      if (status && row.発注ステータス !== status) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredData);
  }

  // CSVエクスポート関数
  function exportCSV() {
    const headers = ['発注番号', '発注日', '商品名', '数量', '単価', '金額', 'ステータス'];
    const csvData = filteredData.map(row => [
      row.発注番号 || "",
      row.発注日時 ? new Date(row.発注日時).toLocaleDateString('ja-JP') : "",
      row.商品名 || "",
      row.発注数量 || "",
      row.単価 || "",
      row.小計金額 || "",
      row.発注ステータス || ""
    ]);

    const csvContent = '\uFEFF' + [headers, ...csvData]
      .map(row => row.map(field => `"${field}"`).join(','))
      .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const rows = await window.aivicApi.list(5); // 発注履歴テーブル
      if (rows) {
        currentData = rows;
        filteredData = rows;
        renderRows(filteredData);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 検索ボタンイベント
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // クリアボタンイベント
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = "";
    container.querySelector("#end-date").value = "";
    container.querySelector("#order-number").value = "";
    container.querySelector("#product-name").value = "";
    container.querySelector("#category-filter").value = "";
    container.querySelector("#status-filter").value = "";
    filteredData = currentData;
    currentPage = 1;
    renderRows(filteredData);
  });

  // CSVエクスポートボタンイベント
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // 表示件数変更イベント
  container.querySelector("#page-size").addEventListener("change", (e) => {
    pageSize = parseInt(e.target.value);
    currentPage = 1;
    renderRows(filteredData);
  });

  // ページネーションイベント
  btnPrev.addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  btnNext.addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / pageSize);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const reorderBtn = e.target.closest(".reorder-btn");

    if (detailBtn) {
      const orderId = detailBtn.dataset.id;
      // 発注詳細画面への遷移（実装されている場合）
      console.log("発注詳細表示:", orderId);
    }

    if (reorderBtn) {
      const orderId = reorderBtn.dataset.id;
      const orderData = currentData.find(r => r.id === orderId);
      if (orderData && confirm(`${orderData.商品名}を再発注しますか？`)) {
        // 発注入力画面への遷移
        window.showScreen("scr-1780291074387");
      }
    }
  });

  // 初期データ表示
  if (tables[5] && tables[5].records) {
    currentData = tables[5].records;
    filteredData = currentData;
    renderRows(filteredData);
  }

  // 最新データを読み込み
  loadData();
}
